            return (False, None)  # required fields absent
        if n < 2:
            return (False, None)  # trivial dimension not allowed
        if alpha < n + 1 or alpha % (n + 1) != 0:
            return (False, None)  # ensure equality construction via replicated simplex is feasible
        if not isinstance(c_coords, list) or len(c_coords) != n:
            return (False, None)  # centroid must be n-dimensional
        norm2 = sum(int(x) * int(x) for x in c_coords)
        # Parse sum_sq as rational
